def _canonical_matrix_attestation(report: Any, field: str) -> dict[str, Any]:
    """Structurally and semantically validate one matrix attestation report.

    Returns the normalized report that byte-for-byte matches
    :func:`decision_matrix_attestation` output, by running the existing
    :func:`verify_decision_matrix_attestation` validation and recomputation
    against the report's own ``start``/``end``/``digest``. Any structural or
    semantic violation, including a false sub-report digest, raises
    ``ValueError``. The input is never mutated.
    """
    if not isinstance(report, dict) or set(report) != _MATRIX_ATTEST_REPORT_KEYS:
        raise ValueError(
            f"{field} must be a dict with exactly the keys "
            "start, end, cases, matrix, policy, digest"
        )
    start = report["start"]
    end = report["end"]
    digest = report["digest"]
    if not verify_decision_matrix_attestation(
        report, {"start": start, "end": end, "digest": digest}
    ):
        raise ValueError(f"{field} digest does not match its recomputed value")
    return {
        "start": start,
        "end": end,
        "cases": copy.deepcopy(report["cases"]),
        "matrix": copy.deepcopy(report["matrix"]),
        "policy": copy.deepcopy(report["policy"]),
        "digest": digest,
    }


